export type CharacterId = 'male_1' | 'male_2' | 'male_3' | 'female_1' | 'female_2' | 'female_3';
export type Gender = 'male' | 'female';

export interface Outfit {
  id: CharacterId;
  gender: Gender;
  file: string;
  nameKey: string;
  descKey: string;
  swatch: string;
  idlePose?: 'pockets' | 'relaxed';
}

