export const OUTFIT_IDS = Object.keys(OUTFITS) as CharacterId[];

export function outfitsFor(gender: Gender): Outfit[] {
  return OUTFIT_IDS.map((id) => OUTFITS[id]).filter((outfit) => outfit.gender === gender);
}

export function isCharacterId(value: string): value is CharacterId {
  return value in OUTFITS;
}
