import {
  groundHeightAt,
  resolveCircleCylinder,
  resolveCircleOBB,
  type CastleGround,
  type CylinderCollider,
  type OBB,
} from '../core/math';

export interface LayoutBuilding {
  name: string;
  x: number;
  z: number;
  rot: number;
  w: number;
  d: number;
  h: number;
}

export interface LayoutWall extends LayoutBuilding {}

export interface LayoutProp {
  type: 'box' | 'cylinder';
  x: number;
  z: number;
  rot?: number;
  w?: number;
  d?: number;
  r?: number;
  h: number;
}

export interface LayoutInteractable {
  id: string;
  kind: 'sleep' | 'flavor' | 'activity';
  x: number;
  z: number;
  radius: number;
  label: string;
  activity?: string;
}

export interface LayoutNpc {
  id: string;
  x: number;
  z: number;
  yaw: number;
  character: string;
  idle: boolean;
}

export interface LayoutZone {
  id: string;
  label: string;
  x: number;
  z: number;
  r: number;
}

export interface LayoutSeat {
  id: string;
  kind: 'chair' | 'bench';
  x: number;
  z: number;
  yaw: number;
}

export interface TownLayout {
  spawn: { x: number; z: number; yaw: number };
  castle: CastleGround;
  buildings: LayoutBuilding[];
  walls: LayoutWall[];
  props: LayoutProp[];
  interactables: LayoutInteractable[];
  seats: LayoutSeat[];
  npcs: LayoutNpc[];
  zones: LayoutZone[];
}

export interface ResolvedPoint {
  x: number;
  z: number;
  blocked: boolean;
}

const WORLD_RADIUS = 55.2;

export class CollisionWorld {
  readonly castle: CastleGround;
  private readonly boxes: OBB[] = [];
  private readonly cylinders: CylinderCollider[] = [];
  private readonly zones: LayoutZone[];

  constructor(layout: TownLayout) {
    this.castle = layout.castle;
    this.zones = [...layout.zones].sort((a, b) => a.r - b.r);

    for (const building of layout.buildings) {
      this.boxes.push({
        x: building.x,
        z: building.z,
        hw: building.w / 2 + 0.12,
        hd: building.d / 2 + 0.12,
        rot: building.rot,
        h: building.h,
      });
    }

    for (const wall of layout.walls) {
      this.boxes.push({
        x: wall.x,
        z: wall.z,
        hw: wall.w / 2,
        hd: wall.d / 2,
        rot: wall.rot,
        h: wall.h,
      });
    }

    for (const prop of layout.props) {
      if (prop.type === 'box') {
        this.boxes.push({
          x: prop.x,
          z: prop.z,
          hw: (prop.w ?? 1) / 2,
          hd: (prop.d ?? 1) / 2,
          rot: prop.rot ?? 0,
          h: prop.h,
        });
      } else {
        this.cylinders.push({ x: prop.x, z: prop.z, r: prop.r ?? 0.5, h: prop.h });
      }
    }
  }

  groundAt(x: number, z: number): number {
    return groundHeightAt(x, z, this.castle);
  }

  /**
   * Resolve a circle against the town. Two passes handle corners where the
   * player is pressed between a building and a low wall.
   */
  resolve(x: number, z: number, radius: number, feetY: number): ResolvedPoint {
    let px = x;
    let pz = z;
    let blocked = false;

    const platformTop = this.castle.height + 0.12;
    const onPlatform = feetY > platformTop - 0.5;

    for (let pass = 0; pass < 2; pass += 1) {
      for (const box of this.boxes) {
        const result = resolveCircleOBB(px, pz, radius, box);
        if (result.hit) {
          px = result.x;
          pz = result.z;
          blocked = true;
        }
      }
      for (const cylinder of this.cylinders) {
        const result = resolveCircleCylinder(px, pz, radius, cylinder);
        if (result.hit) {
          px = result.x;
          pz = result.z;
          blocked = true;
        }
      }

      if (!onPlatform) {
        const dx = px - this.castle.x;
        const dz = pz - this.castle.z;
        const distance = Math.hypot(dx, dz);
        const stair = this.castle.stair;
        const inStair =
          Math.abs(px - stair.x) <= stair.halfWidth - 0.12 &&
          pz >= stair.zMin - 0.6 &&
          pz <= stair.zMax + 0.2;

        if (distance < this.castle.radius + radius && !inStair) {
          const limited = this.castle.radius + radius;
          const nx = distance > 1e-5 ? dx / distance : 0;
          const nz = distance > 1e-5 ? dz / distance : 1;
          px = this.castle.x + nx * limited;
          pz = this.castle.z + nz * limited;
          blocked = true;
        }
      }
    }

    const boundary = Math.hypot(px, pz);
    if (boundary > WORLD_RADIUS) {
      px = (px / boundary) * WORLD_RADIUS;
      pz = (pz / boundary) * WORLD_RADIUS;
      blocked = true;
    }

    return { x: px, z: pz, blocked };
  }

  zoneAt(x: number, z: number): LayoutZone | null {
    let best: LayoutZone | null = null;
    for (const zone of this.zones) {
      const distance = Math.hypot(x - zone.x, z - zone.z);
      if (distance <= zone.r) {
        best = zone;
        break;
      }
    }
    return best;
  }
}
