export const DAY_START = 7 * 60;
export const DAY_END = 24 * 60;
/** The whole day lasts twelve real minutes. */
export const DAY_DURATION_SECONDS = 12 * 60;
const MINUTES_PER_SECOND = (DAY_END - DAY_START) / DAY_DURATION_SECONDS;

export type DayPhase = 'morning' | 'day' | 'evening' | 'night';

const formatters = new Map<string, Intl.DateTimeFormat>();

function formatter(locale: string): Intl.DateTimeFormat {
  let value = formatters.get(locale);
  if (!value) {
    value = new Intl.DateTimeFormat(locale === 'id' ? 'id-ID' : 'en-GB', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    formatters.set(locale, value);
  }
  return value;
}

export class GameClock {
  minutes = DAY_START;
  day = 1;

  constructor(minutes = DAY_START, day = 1) {
    this.minutes = Math.min(DAY_END, Math.max(DAY_START, minutes));
    this.day = Math.max(1, Math.floor(day));
  }

  /** Advance time. Returns true when the day rolled over. */
  update(dt: number): boolean {
    this.minutes += dt * MINUTES_PER_SECOND;
    if (this.minutes >= DAY_END) {
      this.minutes = DAY_START;
      this.day += 1;
      return true;
    }
    return false;
  }

  nextDay(): void {
    this.minutes = DAY_START;
    this.day += 1;
  }

  setTime(minutes: number): void {
    this.minutes = Math.min(DAY_END, Math.max(DAY_START, minutes));
  }

  /** 0 at sunrise, 1 at midnight. Used for warmth and lamp intensity. */
  get dayProgress(): number {
    return (this.minutes - DAY_START) / (DAY_END - DAY_START);
  }

  get phase(): DayPhase {
    if (this.minutes < 9 * 60) return 'morning';
    if (this.minutes < 17 * 60) return 'day';
    if (this.minutes < 20 * 60) return 'evening';
    return 'night';
  }

  get isLate(): boolean {
    return this.minutes >= 20 * 60 + 30;
  }

  format(locale: string): string {
    const hours = Math.floor(this.minutes / 60);
    const minutes = Math.floor(this.minutes % 60);
    const date = new Date(2026, 0, 1, hours, minutes, 0, 0);
    return formatter(locale).format(date);
  }

  isoDay(): string {
    return `day-${this.day}`;
  }
}
