import type { Locale } from './settings';

const GEO_CACHE_KEY = 'dailylife.geo.v1';
const GEO_CACHE_TTL = 7 * 24 * 60 * 60 * 1000;
const GEO_ENDPOINT = 'https://ipwho.is/';

interface GeoCache {
  country: string;
  at: number;
}

/**
 * Pure decision function, kept separate so it can be tested and explained.
 * A successful network lookup is authoritative; the browser language is only
 * a fallback when the lookup fails or is blocked.
 */
export function localeFromSignals(country: string | null, languages: readonly string[]): Locale {
  if (country) {
    return country.toUpperCase() === 'ID' ? 'id' : 'en';
  }
  return languages.some((language) => language.toLowerCase().startsWith('id')) ? 'id' : 'en';
}

export function browserLanguages(): readonly string[] {
  if (typeof navigator === 'undefined') return ['en'];
  return navigator.languages?.length ? navigator.languages : [navigator.language || 'en'];
}

function readGeoCache(): string | null {
  try {
    const raw = localStorage.getItem(GEO_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as GeoCache;
    if (!parsed.country || Date.now() - parsed.at > GEO_CACHE_TTL) return null;
    return parsed.country;
  } catch {
    return null;
  }
}

function writeGeoCache(country: string): void {
  try {
    localStorage.setItem(GEO_CACHE_KEY, JSON.stringify({ country, at: Date.now() } satisfies GeoCache));
  } catch {
    // A cache miss only costs one extra request next time.
  }
}

async function lookupCountry(): Promise<string | null> {
  const cached = readGeoCache();
  if (cached) return cached;

  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 1500);
  try {
    const response = await fetch(GEO_ENDPOINT, {
      signal: controller.signal,
      headers: { Accept: 'application/json' },
    });
    if (!response.ok) return null;
    const data = (await response.json()) as { success?: boolean; country_code?: string };
    if (!data.success || !data.country_code) return null;
    writeGeoCache(data.country_code);
    return data.country_code;
  } catch {
    // Offline, privacy blocker, or a slow endpoint. The game must still boot.
    return null;
  } finally {
    window.clearTimeout(timeout);
  }
}

export async function detectLocale(): Promise<Locale> {
  const country = await lookupCountry();
  return localeFromSignals(country, browserLanguages());
}
