import * as THREE from 'three';

interface Keyframe {
  minute: number;
  top: number;
  horizon: number;
  ground: number;
  sun: number;
  fog: number;
  sunIntensity: number;
  hemiIntensity: number;
  glow: number;
  exposure: number;
}

const KEYFRAMES: Keyframe[] = [
  { minute: 0, top: 0x0b1522, horizon: 0x1d2a36, ground: 0x121a1d, sun: 0x8ba2c2, fog: 0x1b2733, sunIntensity: 0.1, hemiIntensity: 0.3, glow: 0.95, exposure: 1.02 },
  { minute: 300, top: 0x243349, horizon: 0x8e7c74, ground: 0x2c2f2b, sun: 0xd3977a, fog: 0x6c625f, sunIntensity: 0.35, hemiIntensity: 0.6, glow: 0.55, exposure: 1.0 },
  { minute: 420, top: 0x6f98bd, horizon: 0xdde8ea, ground: 0x6b6a5b, sun: 0xffe6c2, fog: 0xc9d3d4, sunIntensity: 2.0, hemiIntensity: 1.1, glow: 0.18, exposure: 1.03 },
  { minute: 780, top: 0x4f86b8, horizon: 0xdfeaec, ground: 0x70745f, sun: 0xfff6e2, fog: 0xcdd9da, sunIntensity: 2.35, hemiIntensity: 1.2, glow: 0.0, exposure: 1.01 },
  { minute: 1020, top: 0x7fa5c2, horizon: 0xf0e1ca, ground: 0x6c6655, sun: 0xffd9a6, fog: 0xd5d0c2, sunIntensity: 2.05, hemiIntensity: 1.0, glow: 0.18, exposure: 1.02 },
  { minute: 1110, top: 0x6c7f93, horizon: 0xe2a273, ground: 0x4c4a42, sun: 0xff9d5c, fog: 0xb09279, sunIntensity: 1.1, hemiIntensity: 0.72, glow: 0.72, exposure: 1.02 },
  { minute: 1230, top: 0x2b3a4d, horizon: 0x6b5a63, ground: 0x2b302e, sun: 0x8f6f6c, fog: 0x4a4a50, sunIntensity: 0.24, hemiIntensity: 0.42, glow: 1.0, exposure: 1.05 },
  { minute: 1320, top: 0x0f1725, horizon: 0x232f3d, ground: 0x161d1f, sun: 0x5c718f, fog: 0x1e2934, sunIntensity: 0.1, hemiIntensity: 0.3, glow: 1.0, exposure: 1.06 },
  { minute: 1440, top: 0x0b1522, horizon: 0x1d2a36, ground: 0x121a1d, sun: 0x8ba2c2, fog: 0x1b2733, sunIntensity: 0.1, hemiIntensity: 0.3, glow: 0.95, exposure: 1.02 },
];

export interface TimePalette {
  top: THREE.Color;
  horizon: THREE.Color;
  ground: THREE.Color;
  sun: THREE.Color;
  fog: THREE.Color;
  sunIntensity: number;
  hemiIntensity: number;
  glow: number;
  exposure: number;
}

const colorCache = new Map<number, THREE.Color>();
function color(hex: number): THREE.Color {
  let value = colorCache.get(hex);
  if (!value) {
    value = new THREE.Color(hex);
    colorCache.set(hex, value);
  }
  return value;
}

export function paletteAt(minutes: number): TimePalette {
  const time = ((minutes % 1440) + 1440) % 1440;

  let from = KEYFRAMES[0];
  let to = KEYFRAMES[KEYFRAMES.length - 1];
  for (let i = 0; i < KEYFRAMES.length - 1; i += 1) {
    if (time >= KEYFRAMES[i].minute && time <= KEYFRAMES[i + 1].minute) {
      from = KEYFRAMES[i];
      to = KEYFRAMES[i + 1];
      break;
    }
  }

  const span = to.minute - from.minute || 1;
  const t = THREE.MathUtils.smoothstep((time - from.minute) / span, 0, 1);
  const mix = (a: number, b: number): THREE.Color => color(a).clone().lerp(color(b), t);
  const number = (a: number, b: number): number => a + (b - a) * t;

  return {
    top: mix(from.top, to.top),
    horizon: mix(from.horizon, to.horizon),
    ground: mix(from.ground, to.ground),
    sun: mix(from.sun, to.sun),
    fog: mix(from.fog, to.fog),
    sunIntensity: number(from.sunIntensity, to.sunIntensity),
    hemiIntensity: number(from.hemiIntensity, to.hemiIntensity),
    glow: number(from.glow, to.glow),
    exposure: number(from.exposure, to.exposure),
  };
}

/** Direction from the town toward the sun, in world space. */
export function sunDirectionAt(minutes: number, target = new THREE.Vector3()): THREE.Vector3 {
  const time = ((minutes % 1440) + 1440) % 1440;
  const daylight = THREE.MathUtils.clamp((time - 360) / 840, 0, 1);
  const elevation = Math.max(0.12, Math.sin(daylight * Math.PI));
  const horizontal = Math.cos(daylight * Math.PI);
  // Keep the sun on the southern side of the sky. The player approaches the
  // castle from the south, so a northern sun would leave every visible facade
  // in shadow and make the town read as dusk at seven in the morning.
  return target.set(horizontal, elevation, 0.5).normalize();
}

export class Sky {
  readonly mesh: THREE.Mesh;
  private readonly material: THREE.ShaderMaterial;

  constructor() {
    this.material = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      depthTest: false,
      fog: false,
      uniforms: {
        uTop: { value: new THREE.Color(0x8fa9bd) },
        uHorizon: { value: new THREE.Color(0xe0d4c2) },
        uGround: { value: new THREE.Color(0x5b5d51) },
        uSunColor: { value: new THREE.Color(0xffd7a4) },
        uSunDirection: { value: new THREE.Vector3(0.3, 0.6, -0.5).normalize() },
      },
      vertexShader: /* glsl */ `
        varying vec3 vDirection;
        void main() {
          vDirection = normalize( position );
          gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
        }
      `,
      fragmentShader: /* glsl */ `
        uniform vec3 uTop;
        uniform vec3 uHorizon;
        uniform vec3 uGround;
        uniform vec3 uSunColor;
        uniform vec3 uSunDirection;
        varying vec3 vDirection;

        float hash( vec2 p ) {
          return fract( sin( dot( p, vec2( 127.1, 311.7 ) ) ) * 43758.5453 );
        }

        float noise( vec2 p ) {
          vec2 i = floor( p );
          vec2 f = fract( p );
          f = f * f * ( 3.0 - 2.0 * f );
          return mix(
            mix( hash( i ), hash( i + vec2( 1.0, 0.0 ) ), f.x ),
            mix( hash( i + vec2( 0.0, 1.0 ) ), hash( i + vec2( 1.0, 1.0 ) ), f.x ),
            f.y
          );
        }

        float fbm( vec2 p ) {
          float value = 0.0;
          float amplitude = 0.5;
          for ( int i = 0; i < 4; i += 1 ) {
            value += noise( p ) * amplitude;
            p = p * 2.03 + 11.7;
            amplitude *= 0.5;
          }
          return value;
        }

        void main() {
          vec3 direction = normalize( vDirection );
          float height = direction.y;
          float skyMix = smoothstep( -0.03, 0.42, height );
          vec3 sky = mix( uHorizon, uTop, skyMix );
          sky = mix( uGround, sky, smoothstep( -0.24, 0.01, height ) );

          float sun = max( dot( direction, normalize( uSunDirection ) ), 0.0 );
          float halo = pow( sun, 7.0 ) * 0.22;
          float disc = pow( sun, 260.0 ) * 0.85;
          sky += uSunColor * ( halo + disc );

          // Thin, slow clouds projected on a dome plane. They only appear
          // above the horizon and pick up the sun's colour near the light.
          vec2 cloudUv = direction.xz / max( height + 0.12, 0.04 );
          float cloudNoise = fbm( cloudUv * 0.55 + vec2( 3.1, 8.4 ) );
          float cloud = smoothstep( 0.54, 0.78, cloudNoise ) * smoothstep( 0.0, 0.16, height );
          cloud *= 0.5 + 0.5 * smoothstep( -0.2, 0.35, height );
          vec3 cloudColor = mix( uHorizon, vec3( 1.0 ), 0.55 ) + uSunColor * ( halo * 1.2 );
          sky = mix( sky, cloudColor, cloud * 0.55 );

          gl_FragColor = vec4( sky, 1.0 );
        }
      `,
    });

    const geometry = new THREE.SphereGeometry(320, 32, 20);
    this.mesh = new THREE.Mesh(geometry, this.material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = -10;
    this.mesh.name = 'SkyDome';
  }

  update(camera: THREE.Camera, palette: TimePalette, sunDirection: THREE.Vector3): void {
    this.mesh.position.copy(camera.position);
    this.material.uniforms.uTop.value.copy(palette.top);
    this.material.uniforms.uHorizon.value.copy(palette.horizon);
    this.material.uniforms.uGround.value.copy(palette.ground);
    this.material.uniforms.uSunColor.value.copy(palette.sun);
    this.material.uniforms.uSunDirection.value.copy(sunDirection);
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    this.material.dispose();
  }
}
