import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';
import { assetUrl } from '../core/assets';
import { clamp, damp, dampAngle, lerp } from '../core/math';
import { applyCurvedWorld, createCurvedDepthMaterial, type CurveUniforms } from '../render/curved';
import { OUTFITS, type CharacterId } from './catalog';

interface Joints {
  hips: THREE.Object3D;
  spine: THREE.Object3D;
  chest: THREE.Object3D;
  neck: THREE.Object3D;
  head: THREE.Object3D;
  shoulderL: THREE.Object3D;
  shoulderR: THREE.Object3D;
  elbowL: THREE.Object3D;
  elbowR: THREE.Object3D;
  handL: THREE.Object3D;
  handR: THREE.Object3D;
  hipL: THREE.Object3D;
  hipR: THREE.Object3D;
  kneeL: THREE.Object3D;
  kneeR: THREE.Object3D;
  ankleL: THREE.Object3D;
  ankleR: THREE.Object3D;
}

const JOINT_NAMES: Record<keyof Joints, string> = {
  hips: 'Joint_Hips',
  spine: 'Joint_Spine',
  chest: 'Joint_Chest',
  neck: 'Joint_Neck',
  head: 'Joint_Head',
  shoulderL: 'Joint_ShoulderL',
  shoulderR: 'Joint_ShoulderR',
  elbowL: 'Joint_ElbowL',
  elbowR: 'Joint_ElbowR',
  handL: 'Joint_HandL',
  handR: 'Joint_HandR',
  hipL: 'Joint_HipL',
  hipR: 'Joint_HipR',
  kneeL: 'Joint_KneeL',
  kneeR: 'Joint_KneeR',
  ankleL: 'Joint_AnkleL',
  ankleR: 'Joint_AnkleR',
};

export interface Motion {
  speed: number;
  airborne: boolean;
}

export type GreetingKind = 'wave' | 'hello';

const SIT_HIP_DROP = 0.34;
const SIT_HIP_ANGLE = 1.38;
const SIT_KNEE_ANGLE = -1.43;
const SIT_ANKLE_ANGLE = 0.10;

export class Character {
  readonly container = new THREE.Group();
  private readonly model: THREE.Object3D;
  private readonly joints: Joints;
  private readonly materials: THREE.Material[] = [];
  private readonly depthMaterial: THREE.MeshDepthMaterial;
  private readonly hipsBaseY: number;
  private readonly handsInPockets: boolean;
  private phase = 0;
  private idleTime = Math.random() * 100;
  private move = 0;
  private air = 0;
  private sit = 0;
  private seated = false;
  private gesture: { kind: GreetingKind; elapsed: number; duration: number } | null = null;
  private gazeX = 0;
  private gazeY = 0;
  private gazeTargetX = 0;
  private gazeTargetY = 0;
  private gazeTimer = 0;
  private shiftPhase = Math.random() * Math.PI * 2;

  constructor(
    model: THREE.Object3D,
    curve: CurveUniforms,
    private readonly maxWalkSpeed = 2.6,
    handsInPockets = false,
  ) {
    this.model = model;
    this.handsInPockets = handsInPockets;
    this.container.add(model);

    this.model.traverse((object) => {
      if (!(object instanceof THREE.Mesh)) return;
      const source = Array.isArray(object.material) ? object.material : [object.material];
      const cloned = source.map((material) => {
        const next = material.clone() as THREE.MeshStandardMaterial;
        if ('roughness' in next) next.roughness = Math.min(0.95, (next.roughness ?? 0.8) + 0.05);
        next.shadowSide = THREE.FrontSide;
        applyCurvedWorld(next, curve);
        this.materials.push(next);
        return next;
      });
      object.material = Array.isArray(object.material) ? cloned : cloned[0];
      object.castShadow = true;
      object.receiveShadow = true;
    });

    this.depthMaterial = createCurvedDepthMaterial(curve);
    this.model.traverse((object) => {
      if (object instanceof THREE.Mesh) object.customDepthMaterial = this.depthMaterial;
    });

    const found: Partial<Joints> = {};
    this.model.traverse((object) => {
      for (const [key, name] of Object.entries(JOINT_NAMES)) {
        if (object.name === name) found[key as keyof Joints] = object;
      }
    });

    if (Object.keys(found).length !== Object.keys(JOINT_NAMES).length) {
      throw new Error('Character model is missing expected joints');
    }

    this.joints = found as Joints;
    this.hipsBaseY = this.joints.hips.position.y;
    this.gazeTimer = 1.5 + Math.random() * 3;
  }

  setPosition(x: number, y: number, z: number): void {
    this.container.position.set(x, y, z);
  }

  setYaw(yaw: number): void {
    this.container.rotation.y = yaw;
  }

  faceTowards(x: number, z: number, dt: number, rate = 12): void {
    const desired = Math.atan2(-x, -z);
    this.container.rotation.y = dampAngle(this.container.rotation.y, desired, rate, dt);
  }

  setVisible(visible: boolean): void {
    this.container.visible = visible;
  }

  /** Start a short greeting gesture. NPCs wave; the player raises a hand. */
  greet(kind: GreetingKind = 'wave'): void {
    if (this.gesture) return;
    this.gesture = { kind, elapsed: 0, duration: kind === 'wave' ? 1.8 : 1.15 };
  }

  /** Blend into a seated pose without moving the character root. */
  setSeated(seated: boolean): void {
    this.seated = seated;
  }

  get isSeated(): boolean {
    return this.seated;
  }

  private gestureWeight(dt: number): number {
    const gesture = this.gesture;
    if (!gesture) return 0;
    gesture.elapsed += dt;
    if (gesture.elapsed >= gesture.duration) {
      this.gesture = null;
      return 0;
    }
    const fadeIn = clamp(gesture.elapsed / 0.22, 0, 1);
    const fadeOut = clamp((gesture.duration - gesture.elapsed) / 0.32, 0, 1);
    const smooth = (value: number): number => value * value * (3 - 2 * value);
    return smooth(fadeIn) * smooth(fadeOut);
  }

  update(dt: number, motion: Motion): void {
    const targetMove = Math.min(1, motion.speed / this.maxWalkSpeed);
    this.move = damp(this.move, targetMove, 9, dt);
    this.air = damp(this.air, motion.airborne ? 1 : 0, 9, dt);
    this.sit = damp(this.sit, this.seated ? 1 : 0, 5.5, dt);
    this.idleTime += dt;
    this.phase += motion.speed * dt * 2.2;

    const move = this.move;
    const air = this.air;
    const sit = this.sit;
    const idle = 1 - move;
    const run = Math.max(0, Math.min(1, (motion.speed - this.maxWalkSpeed) / (this.maxWalkSpeed * 1.4)));
    const swing = Math.sin(this.phase);
    const { joints } = this;

    // Two slow, overlapping waves make the chest expand and settle instead of
    // pulsing on a single metronome beat.
    const breath = Math.sin(this.idleTime * 1.24);
    const breath2 = Math.sin(this.idleTime * 1.24 + 1.7);
    const sway = Math.sin(this.idleTime * 0.34 + this.shiftPhase);
    const breathAmount = idle * (1 - sit * 0.35);

    this.updateGaze(dt, move);

    // Legs. Positive rotation.x on a hip swings the foot forward because the
    // model faces -Z; knees bend with a negative rotation.
    const hipSwing = swing * (0.46 + run * 0.22) * move;
    const armSwing = -swing * (0.38 + run * 0.24) * move;

    let hipLX = hipSwing + air * 0.32;
    let hipRX = -hipSwing + air * 0.18;
    let kneeLX = -Math.max(0, -swing) * (1.05 + run * 0.5) * move - air * 0.72;
    let kneeRX = -Math.max(0, swing) * (1.05 + run * 0.5) * move - air * 0.5;
    let ankleLX = hipSwing * 0.35 + Math.max(0, -swing) * 0.25 * move + air * 0.25;
    let ankleRX = -hipSwing * 0.35 + Math.max(0, swing) * 0.25 * move + air * 0.18;

    if (sit > 0.001) {
      // One foot is a little further forward so the seated silhouette is not
      // perfectly symmetrical.
      hipLX = lerp(hipLX, SIT_HIP_ANGLE + 0.03, sit);
      hipRX = lerp(hipRX, SIT_HIP_ANGLE - 0.035, sit);
      kneeLX = lerp(kneeLX, SIT_KNEE_ANGLE + 0.02, sit);
      kneeRX = lerp(kneeRX, SIT_KNEE_ANGLE - 0.025, sit);
      ankleLX = lerp(ankleLX, SIT_ANKLE_ANGLE, sit);
      ankleRX = lerp(ankleRX, SIT_ANKLE_ANGLE - 0.02, sit);
    }

    joints.hipL.rotation.x = hipLX;
    joints.hipR.rotation.x = hipRX;
    joints.kneeL.rotation.x = kneeLX;
    joints.kneeR.rotation.x = kneeRX;
    joints.ankleL.rotation.x = ankleLX;
    joints.ankleR.rotation.x = ankleRX;

    // Arms. Idle arms hang with a small natural bend; one outfit keeps its
    // hands in the trouser pockets, as in the reference.
    const pocket = this.handsInPockets ? clamp((idle - 0.35) / 0.4, 0, 1) * (1 - sit) : 0;

    let shoulderLX = armSwing - air * 0.24;
    let shoulderRX = -armSwing - air * 0.18;
    let shoulderLZ = 0.06 + Math.sin(this.idleTime * 1.4) * 0.006 + air * 0.2;
    let shoulderRZ = -0.06 - Math.sin(this.idleTime * 1.4 + 0.7) * 0.006 - air * 0.16;
    let elbowLX = 0.1 + move * 0.18 + Math.max(0, swing) * 0.24 * move + air * 0.35;
    let elbowRX = 0.1 + move * 0.18 + Math.max(0, -swing) * 0.24 * move + air * 0.3;
    let elbowLZ = 0;
    let elbowRZ = 0;
    let handLX = 0;
    let handRX = 0;
    let handLZ = 0;
    let handRZ = 0;

    if (pocket > 0.001) {
      shoulderLX = lerp(shoulderLX, 0.08, pocket);
      shoulderRX = lerp(shoulderRX, 0.08, pocket);
      // Elbows angle slightly away from the body while the hands slip into
      // the front pockets.
      shoulderLZ = lerp(shoulderLZ, 0.10, pocket);
      shoulderRZ = lerp(shoulderRZ, -0.10, pocket);
      elbowLX = lerp(elbowLX, 0.58, pocket);
      elbowRX = lerp(elbowRX, 0.58, pocket);
      handLX = lerp(handLX, -0.44, pocket);
      handRX = lerp(handRX, -0.44, pocket);
    }

    if (sit > 0.001) {
      shoulderLX = lerp(shoulderLX, 0.48, sit);
      shoulderRX = lerp(shoulderRX, 0.48, sit);
      shoulderLZ = lerp(shoulderLZ, -0.10, sit);
      shoulderRZ = lerp(shoulderRZ, 0.10, sit);
      elbowLX = lerp(elbowLX, 0.82, sit);
      elbowRX = lerp(elbowRX, 0.82, sit);
      handLX = lerp(handLX, -0.12, sit);
      handRX = lerp(handRX, -0.12, sit);
    }

    const gesture = this.gesture;
    const gestureWeight = this.gestureWeight(dt);
    if (gesture && gestureWeight > 0.001) {
      const t = gesture.elapsed;
      const wave = gesture.kind === 'wave';
      const wavePhase = Math.sin((t - 0.18) * 10.5);
      shoulderRX = lerp(shoulderRX, wave ? -0.14 : -0.10, gestureWeight);
      shoulderRZ = lerp(shoulderRZ, wave ? -1.92 : -0.86, gestureWeight);
      elbowRX = lerp(elbowRX, wave ? 0.10 : 0.22, gestureWeight);
      elbowRZ = lerp(elbowRZ, wave ? -0.58 : -1.55, gestureWeight);
      handRZ = lerp(handRZ, wave ? 0.24 + wavePhase * 0.38 : 0.10 + wavePhase * 0.22, gestureWeight);
      handRX = lerp(handRX, wave ? -0.10 : -0.04, gestureWeight);
    }

    joints.shoulderL.rotation.x = shoulderLX;
    joints.shoulderR.rotation.x = shoulderRX;
    joints.shoulderL.rotation.z = shoulderLZ;
    joints.shoulderR.rotation.z = shoulderRZ;
    joints.elbowL.rotation.x = elbowLX;
    joints.elbowR.rotation.x = elbowRX;
    joints.elbowL.rotation.z = elbowLZ;
    joints.elbowR.rotation.z = elbowRZ;
    joints.handL.rotation.x = handLX;
    joints.handR.rotation.x = handRX;
    joints.handL.rotation.z = handLZ;
    joints.handR.rotation.z = handRZ;

    // Body weight, breathing, and the seated hip drop.
    const bob = (1 - Math.cos(this.phase * 2)) * 0.5 * 0.045 * move;
    const breathRise = (breath * 0.0065 + breath2 * 0.0018) * breathAmount;
    joints.hips.position.y = this.hipsBaseY + bob + breathRise + air * 0.03 - SIT_HIP_DROP * sit;
    joints.hips.rotation.z = (Math.sin(this.phase) * 0.035 * move + sway * 0.012 * idle) * (1 - sit);
    joints.hips.rotation.y = Math.sin(this.phase) * 0.08 * move;

    const lean = 0.02 + move * 0.05 + run * 0.08 - air * 0.04 + sit * 0.04;
    joints.spine.rotation.x = lean + breath * 0.005 * breathAmount;
    joints.spine.rotation.z = -sway * 0.010 * breathAmount;
    joints.spine.rotation.y = -Math.sin(this.phase) * 0.035 * move;
    joints.chest.rotation.y = -Math.sin(this.phase) * 0.075 * move;
    joints.chest.rotation.x =
      breath * 0.014 * breathAmount + breath2 * 0.003 * breathAmount + run * 0.05 - sit * 0.015;
    joints.chest.rotation.z = sway * 0.008 * breathAmount;

    // Head stays level; small idle glances and a greeting nod keep the
    // character from feeling frozen.
    const nod = gesture && gesture.kind === 'hello' ? Math.sin(clamp(t01(gesture.elapsed, 0.7), 0, 1) * Math.PI) * 0.09 * gestureWeight : 0;
    joints.neck.rotation.x = -joints.spine.rotation.x * 0.45 + sit * 0.01;
    joints.neck.rotation.y = this.gazeY * 0.35 * breathAmount;
    joints.head.rotation.y = this.gazeX * breathAmount + Math.sin(this.idleTime * 0.21) * 0.012 * breathAmount;
    joints.head.rotation.x = this.gazeY * breathAmount + nod - breath * 0.004 * breathAmount;
    joints.head.rotation.z = sway * 0.008 * breathAmount;
  }

  private updateGaze(dt: number, move: number): void {
    this.gazeTimer -= dt;
    if (this.gazeTimer <= 0) {
      this.gazeTimer = 1.8 + Math.random() * 3.4;
      // Look around a little, but keep most of the gaze near the camera line.
      this.gazeTargetX = (Math.random() - 0.5) * 0.34 * (1 - move);
      this.gazeTargetY = (Math.random() - 0.5) * 0.08 * (1 - move);
    }
    this.gazeX = damp(this.gazeX, this.gazeTargetX, 2.8, dt);
    this.gazeY = damp(this.gazeY, this.gazeTargetY, 2.8, dt);
  }

  /** A quiet, upright pose for the character select preview. */
  updatePreview(dt: number): void {
    this.update(dt, { speed: 0, airborne: false });
  }

  dispose(): void {
    for (const material of this.materials) material.dispose();
    this.depthMaterial.dispose();
    this.container.removeFromParent();
  }
}

function t01(value: number, duration: number): number {
  return value / duration;
}

export class CharacterLibrary {
  private readonly loader = new GLTFLoader();
  private readonly sources = new Map<CharacterId, THREE.Object3D>();
  private loaded = 0;

  constructor() {
    this.loader.setMeshoptDecoder(MeshoptDecoder);
  }

  async loadAll(onProgress?: (fraction: number) => void): Promise<void> {
    const ids = Object.keys(OUTFITS) as CharacterId[];
    await Promise.all(
      ids.map(async (id) => {
        const gltf = await this.loader.loadAsync(assetUrl(OUTFITS[id].file));
        this.sources.set(id, gltf.scene);
        this.loaded += 1;
        onProgress?.(this.loaded / ids.length);
      }),
    );
  }

  create(id: CharacterId, curve: CurveUniforms): Character {
    const source = this.sources.get(id);
    if (!source) throw new Error(`Character ${id} was not loaded`);
    const clone = source.clone(true);
    clone.name = `Character_${id}`;
    return new Character(clone, curve, 2.6, OUTFITS[id].idlePose === 'pockets');
  }

  dispose(): void {
    for (const source of this.sources.values()) {
      source.traverse((object) => {
        if (object instanceof THREE.Mesh) object.geometry.dispose();
      });
    }
    this.sources.clear();
  }
}
