import { Character } from '../characters/character';
import { dampAngle, mulberry32 } from '../core/math';
import type { CollisionWorld, LayoutNpc } from '../world/collision';

export class Npc {
  readonly character: Character;
  readonly definition: LayoutNpc;
  private readonly homeX: number;
  private readonly homeZ: number;
  private readonly random: () => number;
  private targetX: number;
  private targetZ: number;
  private pauseTimer: number;
  private walkTimer = 0;
  private moving = false;
  private speed = 0;
  private greetTimer: number;
  talking = false;

  constructor(definition: LayoutNpc, character: Character, private readonly collision: CollisionWorld, seed: number) {
    this.definition = definition;
    this.character = character;
    this.homeX = definition.x;
    this.homeZ = definition.z;
    this.targetX = definition.x;
    this.targetZ = definition.z;
    this.random = mulberry32(seed * 7919 + 13);
    this.pauseTimer = 1 + this.random() * 4;
    this.greetTimer = 5 + this.random() * 9;
    this.character.setPosition(definition.x, collision.groundAt(definition.x, definition.z), definition.z);
    this.character.setYaw(definition.yaw);
  }

  greet(kind: 'wave' | 'hello' = 'wave'): void {
    this.character.greet(kind);
  }

  get x(): number {
    return this.character.container.position.x;
  }

  get z(): number {
    return this.character.container.position.z;
  }

  update(dt: number, playerX: number, playerZ: number): void {
    const distance = Math.hypot(playerX - this.x, playerZ - this.z);
    const engaged = this.talking || distance < 3.6;
    this.greetTimer -= dt;

    if (engaged) {
      this.speed = 0;
      this.character.faceTowards(playerX - this.x, playerZ - this.z, dt, 6);
      // A neighbour looks up and waves when you come close, then gets back to
      // their day for a while.
      if (!this.talking && distance < 3.2 && this.greetTimer <= 0) {
        this.character.greet('wave');
        this.greetTimer = 14 + this.random() * 12;
      }
    } else if (!this.definition.idle) {
      this.wander(dt);
    } else {
      this.speed = 0;
      this.character.setYaw(
        dampAngle(this.character.container.rotation.y, this.definition.yaw, 2, dt),
      );
    }

    this.character.update(dt, { speed: this.speed, airborne: false });
  }

  private wander(dt: number): void {
    this.pauseTimer -= dt;
    this.walkTimer -= dt;

    if (this.moving) {
      const dx = this.targetX - this.x;
      const dz = this.targetZ - this.z;
      const distance = Math.hypot(dx, dz);
      if (distance < 0.35 || this.walkTimer <= 0) {
        this.moving = false;
        this.speed = 0;
        this.pauseTimer = 2 + this.random() * 5;
      } else {
        const step = 0.62 * dt;
        const nx = this.x + (dx / distance) * step;
        const nz = this.z + (dz / distance) * step;
        const resolved = this.collision.resolve(nx, nz, 0.3, this.character.container.position.y);
        this.character.setPosition(resolved.x, this.collision.groundAt(resolved.x, resolved.z), resolved.z);
        this.character.faceTowards(dx, dz, dt, 4);
        this.speed = 0.62;
      }
      return;
    }

    if (this.pauseTimer <= 0) {
      const angle = this.random() * Math.PI * 2;
      const radius = 1.2 + this.random() * 2.4;
      this.targetX = this.homeX + Math.cos(angle) * radius;
      this.targetZ = this.homeZ + Math.sin(angle) * radius;
      this.walkTimer = 6 + this.random() * 6;
      this.moving = true;
    }
  }
}

export function createNpc(
  definition: LayoutNpc,
  character: Character,
  collision: CollisionWorld,
  index: number,
): Npc {
  return new Npc(definition, character, collision, index);
}

export function distanceToNpc(npc: Npc, x: number, z: number): number {
  return Math.hypot(npc.x - x, npc.z - z);
}
