export const TAU = Math.PI * 2;

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Frame-rate independent exponential smoothing. */
export function damp(current: number, target: number, lambda: number, dt: number): number {
  return lerp(current, target, 1 - Math.exp(-lambda * dt));
}

export function dampAngle(current: number, target: number, lambda: number, dt: number): number {
  let delta = ((target - current + Math.PI) % TAU) - Math.PI;
  if (delta < -Math.PI) delta += TAU;
  return current + delta * (1 - Math.exp(-lambda * dt));
}

export function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

export function shortestAngle(from: number, to: number): number {
  let delta = ((to - from + Math.PI) % TAU) - Math.PI;
  if (delta < -Math.PI) delta += TAU;
  return delta;
}

export interface OBB {
  x: number;
  z: number;
  hw: number;
  hd: number;
  rot: number;
  h: number;
}

export interface CylinderCollider {
  x: number;
  z: number;
  r: number;
  h: number;
}

export interface ResolvedPosition {
  x: number;
  z: number;
  hit: boolean;
}

/**
 * Push a circle out of an oriented box. The box is treated as a 2D footprint
 * with a height; the caller decides whether the player is low enough to hit it.
 */
export function resolveCircleOBB(px: number, pz: number, radius: number, box: OBB): ResolvedPosition {
  const cos = Math.cos(box.rot);
  const sin = Math.sin(box.rot);
  const dx = px - box.x;
  const dz = pz - box.z;

  // Inverse of a Three.js Y rotation.
  const lx = dx * cos - dz * sin;
  const lz = dx * sin + dz * cos;

  const closestX = clamp(lx, -box.hw, box.hw);
  const closestZ = clamp(lz, -box.hd, box.hd);
  let nx = lx - closestX;
  let nz = lz - closestZ;
  const distSq = nx * nx + nz * nz;

  if (distSq > radius * radius) {
    return { x: px, z: pz, hit: false };
  }

  if (distSq > 1e-8) {
    const dist = Math.sqrt(distSq);
    const push = radius - dist;
    nx /= dist;
    nz /= dist;
    const worldX = nx * cos + nz * sin;
    const worldZ = -nx * sin + nz * cos;
    return { x: px + worldX * push, z: pz + worldZ * push, hit: true };
  }

  // Center is inside the footprint. Push out along the shallowest axis.
  const penX = box.hw - Math.abs(lx) + radius;
  const penZ = box.hd - Math.abs(lz) + radius;
  if (penX < penZ) {
    const sign = lx >= 0 ? 1 : -1;
    nx = sign;
    nz = 0;
    const worldX = nx * cos + nz * sin;
    const worldZ = -nx * sin + nz * cos;
    return { x: px + worldX * penX, z: pz + worldZ * penZ, hit: true };
  }
  const sign = lz >= 0 ? 1 : -1;
  nx = 0;
  nz = sign;
  const worldX = nx * cos + nz * sin;
  const worldZ = -nx * sin + nz * cos;
  return { x: px + worldX * penX, z: pz + worldZ * penZ, hit: true };
}

export function resolveCircleCylinder(
  px: number,
  pz: number,
  radius: number,
  collider: CylinderCollider,
): ResolvedPosition {
  const dx = px - collider.x;
  const dz = pz - collider.z;
  const minDistance = radius + collider.r;
  const distSq = dx * dx + dz * dz;
  if (distSq >= minDistance * minDistance) {
    return { x: px, z: pz, hit: false };
  }
  const dist = Math.sqrt(distSq) || 0.0001;
  const push = minDistance - dist;
  return { x: px + (dx / dist) * push, z: pz + (dz / dist) * push, hit: true };
}

/** Return the fraction along the 2D segment where it enters the box, or null. */
export function segmentOBBHit(
  ax: number,
  az: number,
  bx: number,
  bz: number,
  box: OBB,
): number | null {
  const cos = Math.cos(box.rot);
  const sin = Math.sin(box.rot);
  const toLocal = (x: number, z: number): [number, number] => {
    const dx = x - box.x;
    const dz = z - box.z;
    return [dx * cos - dz * sin, dx * sin + dz * cos];
  };

  const [axl, azl] = toLocal(ax, az);
  const [bxl, bzl] = toLocal(bx, bz);
  const dx = bxl - axl;
  const dz = bzl - azl;

  let tMin = 0;
  let tMax = 1;

  const testAxis = (origin: number, direction: number, min: number, max: number): boolean => {
    if (Math.abs(direction) < 1e-8) {
      return origin >= min && origin <= max;
    }
    let t0 = (min - origin) / direction;
    let t1 = (max - origin) / direction;
    if (t0 > t1) [t0, t1] = [t1, t0];
    tMin = Math.max(tMin, t0);
    tMax = Math.min(tMax, t1);
    return tMin <= tMax;
  };

  if (!testAxis(axl, dx, -box.hw, box.hw)) return null;
  if (!testAxis(azl, dz, -box.hd, box.hd)) return null;
  return tMin;
}

export interface CastleGround {
  x: number;
  z: number;
  radius: number;
  height: number;
  stair: { x: number; zMin: number; zMax: number; halfWidth: number };
}

/** Walkable height for the flat town, castle platform, and its south stair. */
export function groundHeightAt(x: number, z: number, castle: CastleGround): number {
  const platformTop = castle.height + 0.12;
  const dx = x - castle.x;
  const dz = z - castle.z;
  if (dx * dx + dz * dz <= (castle.radius + 0.15) ** 2) {
    return platformTop;
  }

  const stair = castle.stair;
  if (Math.abs(x - stair.x) <= stair.halfWidth && z >= stair.zMin && z <= stair.zMax) {
    const t = (stair.zMax - z) / (stair.zMax - stair.zMin);
    return platformTop * clamp(t, 0, 1);
  }
  return 0;
}

/** A cheap deterministic PRNG for visual details and tests. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
