import { t } from '../i18n';
import type { Locale, Quality, Settings } from '../core/settings';
import type { CharacterId, Gender } from '../characters/catalog';
import { OUTFITS, outfitsFor } from '../characters/catalog';
import { drawPortrait, type PortraitSpec } from './portrait';

export interface HudActivity {
  id: string;
  name: string;
  done: boolean;
}

export interface JournalEntryView extends HudActivity {
  desc: string;
}

export interface UiCallbacks {
  onStart: () => void;
  onContinue: () => void;
  onSelectBack: () => void;
  onConfirm: () => void;
  onGender: (gender: Gender) => void;
  onOutfit: (id: CharacterId) => void;
  onLanguage: (locale: Locale) => void;
  onOpenSettings: (fromGame: boolean) => void;
  onCloseSettings: () => void;
  onOpenCredits: () => void;
  onCloseCredits: () => void;
  onPause: () => void;
  onResume: () => void;
  onReset: () => void;
  onJournalOpen: () => void;
  onJournalClose: () => void;
  onDialogNext: () => void;
  onDialogClosed: () => void;
  onInteract: () => void;
  onQuality: (quality: Quality) => void;
  onCurve: (value: number) => void;
  onSensitivity: (value: number) => void;
  onVolume: (value: number) => void;
}

function byId<T extends HTMLElement>(id: string): T {
  const element = document.getElementById(id);
  if (!element) throw new Error(`Missing element #${id}`);
  return element as T;
}

export class Ui {
  private readonly loading = byId('loading-screen');
  private readonly title = byId('title-screen');
  private readonly select = byId('select-screen');
  private readonly hud = byId('hud');
  private readonly pause = byId('pause-screen');
  private readonly credits = byId('credits-screen');
  private readonly journal = byId('journal');
  private readonly dialog = byId('dialog');
  private readonly toastElement = byId('toast');
  private readonly fade = byId('fade');

  private readonly continueButton = byId<HTMLButtonElement>('btn-continue');
  private readonly outfitList = byId('outfit-list');
  private readonly activityList = byId('hud-activities');
  private readonly journalBody = byId('journal-body');
  private readonly interaction = byId('interaction-prompt');
  private readonly interactionLabel = byId('interaction-label');

  private readonly dialogSpeaker = byId('dialog-speaker');
  private readonly dialogText = byId('dialog-text');
  private readonly dialogPortrait = byId('dialog-portrait');

  private readonly hudDay = byId('hud-day');
  private readonly hudTime = byId('hud-time');
  private readonly hudPlace = byId('hud-place');

  private readonly pauseEyebrow = byId('pause-eyebrow');
  private readonly pauseTitle = byId('pause-title');
  private readonly resumeButton = byId<HTMLButtonElement>('btn-pause-resume');
  private readonly resetButton = byId<HTMLButtonElement>('btn-reset-save');

  private readonly languageSelect = byId<HTMLSelectElement>('setting-language');
  private readonly qualitySelect = byId<HTMLSelectElement>('setting-quality');
  private readonly curveInput = byId<HTMLInputElement>('setting-curve');
  private readonly sensitivityInput = byId<HTMLInputElement>('setting-sensitivity');
  private readonly volumeInput = byId<HTMLInputElement>('setting-volume');

  private dialogLines: string[] = [];
  private dialogIndex = 0;
  private dialogAccent = '#31453b';
  private toastTimer = 0;
  private settingsFromGame = false;
  private currentGender: Gender = 'male';
  private currentOutfit: CharacterId = 'male_1';
  private hudState: { day: number; time: string; place: string; activities: HudActivity[] } | null = null;
  private journalEntries: JournalEntryView[] = [];
  private locale: Locale = 'id';

  constructor(private readonly callbacks: UiCallbacks) {
    this.bind();
  }

  private bind(): void {
    this.continueButton.addEventListener('click', () => this.callbacks.onContinue());
    byId('btn-start').addEventListener('click', () => this.callbacks.onStart());
    byId('btn-select-back').addEventListener('click', () => this.callbacks.onSelectBack());
    byId('btn-confirm').addEventListener('click', () => this.callbacks.onConfirm());
    byId('btn-settings').addEventListener('click', () => this.callbacks.onOpenSettings(false));
    byId('btn-credits').addEventListener('click', () => this.callbacks.onOpenCredits());
    byId('btn-credits-close').addEventListener('click', () => this.callbacks.onCloseCredits());
    byId('btn-pause').addEventListener('click', () => this.callbacks.onPause());
    byId('btn-pause-close').addEventListener('click', () => this.callbacks.onCloseSettings());
    byId('btn-pause-resume').addEventListener('click', () => this.callbacks.onResume());
    byId('btn-reset-save').addEventListener('click', () => this.callbacks.onReset());
    byId('btn-journal-close').addEventListener('click', () => this.callbacks.onJournalClose());
    byId('btn-dialog-next').addEventListener('click', () => this.advanceDialog());

    for (const button of Array.from(document.querySelectorAll<HTMLButtonElement>('[data-gender]'))) {
      button.addEventListener('click', () => this.callbacks.onGender(button.dataset.gender as Gender));
    }

    for (const button of Array.from(document.querySelectorAll<HTMLButtonElement>('[data-lang]'))) {
      button.addEventListener('click', () => this.callbacks.onLanguage(button.dataset.lang as Locale));
    }

    this.languageSelect.addEventListener('change', () => this.callbacks.onLanguage(this.languageSelect.value as Locale));
    this.qualitySelect.addEventListener('change', () => this.callbacks.onQuality(this.qualitySelect.value as Quality));
    this.curveInput.addEventListener('input', () => this.callbacks.onCurve(Number(this.curveInput.value)));
    this.sensitivityInput.addEventListener('input', () =>
      this.callbacks.onSensitivity(Number(this.sensitivityInput.value)),
    );
    this.volumeInput.addEventListener('input', () => this.callbacks.onVolume(Number(this.volumeInput.value)));
    this.interaction.addEventListener('click', () => this.callbacks.onInteract());
  }

  setLocale(locale: Locale): void {
    this.locale = locale;
    for (const button of Array.from(document.querySelectorAll<HTMLButtonElement>('[data-lang]'))) {
      button.classList.toggle('is-active', button.dataset.lang === locale);
      button.setAttribute('aria-pressed', String(button.dataset.lang === locale));
    }
    this.languageSelect.value = locale;
    this.renderOutfits(this.currentGender, this.currentOutfit);
    this.refreshHudText();
    this.renderJournal();
    this.updatePauseHeader();
  }

  syncSettings(settings: Settings): void {
    this.locale = settings.language;
    this.languageSelect.value = settings.language;
    this.qualitySelect.value = settings.quality;
    this.curveInput.value = String(settings.curve);
    this.sensitivityInput.value = String(settings.sensitivity);
    this.volumeInput.value = String(settings.volume);
    this.setLocale(settings.language);
  }

  setLoading(progress: number, labelKey: string): void {
    const bar = byId('loading-progress');
    bar.style.width = `${Math.round(Math.min(1, Math.max(0, progress)) * 100)}%`;
    bar.parentElement?.setAttribute('aria-valuenow', String(Math.round(progress * 100)));
    const label = byId('loading-label');
    label.textContent = t(labelKey);
  }

  showLoading(): void {
    this.loading.hidden = false;
    this.title.hidden = true;
    this.select.hidden = true;
    this.hud.hidden = true;
  }

  showTitle(hasSave: boolean): void {
    this.loading.hidden = true;
    this.title.hidden = false;
    this.select.hidden = true;
    this.hud.hidden = true;
    this.pause.hidden = true;
    this.credits.hidden = true;
    this.continueButton.hidden = !hasSave;
    this.continueButton.textContent = t('title.continue');
  }

  showSelect(): void {
    this.title.hidden = true;
    this.select.hidden = false;
    this.hud.hidden = true;
    this.pause.hidden = true;
    this.credits.hidden = true;
  }

  showGame(): void {
    this.loading.hidden = true;
    this.title.hidden = true;
    this.select.hidden = true;
    this.hud.hidden = false;
  }

  hideAllScreens(): void {
    this.loading.hidden = true;
    this.title.hidden = true;
    this.select.hidden = true;
  }

  selectGender(gender: Gender, outfit: CharacterId): void {
    this.currentGender = gender;
    this.currentOutfit = outfit;
    for (const button of Array.from(document.querySelectorAll<HTMLButtonElement>('[data-gender]'))) {
      const active = button.dataset.gender === gender;
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-selected', String(active));
    }
    this.renderOutfits(gender, outfit);
    this.updatePreviewCaption(outfit);
  }

  private renderOutfits(gender: Gender, active: CharacterId): void {
    this.outfitList.replaceChildren();
    const listings = outfitsFor(gender);
    listings.forEach((outfit, index) => {
      const button = document.createElement('button');
      button.className = `outfit-card${outfit.id === active ? ' is-active' : ''}`;
      button.setAttribute('role', 'option');
      button.setAttribute('aria-selected', String(outfit.id === active));
      button.dataset.outfit = outfit.id;

      const number = document.createElement('span');
      number.className = 'outfit-card__index';
      number.textContent = String(index + 1).padStart(2, '0');

      const body = document.createElement('span');
      const name = document.createElement('span');
      name.className = 'outfit-card__name';
      name.textContent = t(outfit.nameKey);
      const desc = document.createElement('span');
      desc.className = 'outfit-card__desc';
      desc.textContent = t(outfit.descKey);
      body.append(name, desc);

      const swatch = document.createElement('span');
      swatch.className = 'outfit-card__swatch';
      swatch.style.background = outfit.swatch;

      button.append(number, body, swatch);
      button.addEventListener('click', () => this.callbacks.onOutfit(outfit.id));
      this.outfitList.append(button);
    });

    for (const button of Array.from(document.querySelectorAll<HTMLButtonElement>('[data-gender]'))) {
      const genderKey = button.dataset.gender === 'male' ? 'select.male' : 'select.female';
      button.textContent = t(genderKey);
    }
  }

  updatePreviewCaption(outfit: CharacterId): void {
    const name = byId('preview-name');
    const note = byId('preview-note');
    name.textContent = t(OUTFITS[outfit].nameKey);
    note.textContent = t(`characters.${OUTFITS[outfit].gender}.note`);
    this.currentOutfit = outfit;
    this.currentGender = OUTFITS[outfit].gender;
    for (const card of Array.from(this.outfitList.children)) {
      const element = card as HTMLElement;
      const active = element.dataset.outfit === outfit;
      element.classList.toggle('is-active', active);
      element.setAttribute('aria-selected', String(active));
    }
  }

  showPrompt(label: string): void {
    this.interactionLabel.textContent = label;
    this.interaction.hidden = false;
  }

  hidePrompt(): void {
    this.interaction.hidden = true;
  }

  updateHud(state: { day: number; time: string; place: string; activities: HudActivity[] }): void {
    this.hudState = state;
    this.refreshHudText();
  }

  private refreshHudText(): void {
    if (!this.hudState) return;
    this.hudDay.textContent = t('hud.day', { day: this.hudState.day });
    this.hudTime.textContent = this.hudState.time;
    this.hudPlace.textContent = this.hudState.place;
    this.activityList.replaceChildren();
    for (const activity of this.hudState.activities) {
      const item = document.createElement('li');
      item.textContent = activity.name;
      item.classList.toggle('is-done', activity.done);
      this.activityList.append(item);
    }
  }

  updateJournal(entries: JournalEntryView[]): void {
    this.journalEntries = entries;
    this.renderJournal();
  }

  private renderJournal(): void {
    this.journalBody.replaceChildren();
    for (const entry of this.journalEntries) {
      const block = document.createElement('div');
      block.className = `journal-entry${entry.done ? ' is-done' : ''}`;

      const title = document.createElement('div');
      title.className = 'journal-entry__title';
      const name = document.createElement('span');
      name.textContent = entry.name;
      const state = document.createElement('span');
      state.className = 'journal-entry__state';
      state.textContent = entry.done ? t('journal.done') : t('journal.pending');
      title.append(name, state);

      const text = document.createElement('p');
      text.className = 'journal-entry__text';
      text.textContent = entry.desc;

      block.append(title, text);
      this.journalBody.append(block);
    }

    const footer = document.createElement('p');
    footer.className = 'journal-entry__text';
    footer.style.marginTop = '18px';
    footer.textContent = t('journal.footer');
    this.journalBody.append(footer);
  }

  setJournalOpen(open: boolean): void {
    this.journal.hidden = !open;
    if (open) {
      this.toastElement.hidden = true;
      this.renderJournal();
    }
  }

  openSettings(fromGame: boolean): void {
    this.toastElement.hidden = true;
    this.settingsFromGame = fromGame;
    this.pause.hidden = false;
    this.resumeButton.hidden = !fromGame;
    this.resetButton.hidden = !fromGame;
    this.updatePauseHeader();
  }

  closeSettings(): void {
    this.pause.hidden = true;
  }

  openCredits(): void {
    this.toastElement.hidden = true;
    this.credits.hidden = false;
    this.renderCredits();
  }

  closeCredits(): void {
    this.credits.hidden = true;
  }

  private renderCredits(): void {
    const body = byId('credits-body');
    body.replaceChildren();
    const intro = document.createElement('p');
    intro.textContent = t('credits.body');
    const license = document.createElement('p');
    license.textContent = t('credits.license');
    const heading = document.createElement('h3');
    heading.textContent = 'Tools';
    const list = document.createElement('ul');
    for (const line of ['Blender 5.3', 'Three.js (MIT)', 'TypeScript (Apache 2.0)', 'i18next (MIT)', 'Fraunces, Inter (SIL OFL 1.1)']) {
      const item = document.createElement('li');
      item.textContent = line;
      list.append(item);
    }
    body.append(intro, license, heading, list);
  }

  private updatePauseHeader(): void {
    if (this.settingsFromGame) {
      this.pauseEyebrow.textContent = t('pause.eyebrow');
      this.pauseTitle.textContent = t('pause.title');
    } else {
      this.pauseEyebrow.textContent = t('settings.panelEyebrow');
      this.pauseTitle.textContent = t('settings.panelTitle');
    }
  }

  openDialog(speaker: string, lines: string[], accent = '#31453b', portrait?: PortraitSpec): void {
    this.dialogLines = lines.length > 0 ? lines : [''];
    this.dialogIndex = 0;
    this.dialogAccent = accent;
    this.dialogSpeaker.textContent = speaker;
    this.dialogPortrait.replaceChildren();
    if (portrait) {
      const canvas = document.createElement('canvas');
      drawPortrait(canvas, portrait);
      this.dialogPortrait.append(canvas);
    } else {
      this.dialogPortrait.textContent = speaker.slice(0, 1).toUpperCase();
    }
    this.dialogPortrait.style.background = `linear-gradient(150deg, ${accent}, #2b2f2a)`;
    this.dialog.hidden = false;
    document.body.classList.add('is-dialog');
    this.renderDialogLine();
  }

  private renderDialogLine(): void {
    this.dialogText.textContent = this.dialogLines[this.dialogIndex] ?? '';
    const next = byId('btn-dialog-next');
    next.textContent =
      this.dialogIndex < this.dialogLines.length - 1 ? t('dialog.next') : t('common.close');
  }

  advanceDialog(): void {
    if (this.dialog.hidden) return;
    if (this.dialogIndex < this.dialogLines.length - 1) {
      this.dialogIndex += 1;
      this.renderDialogLine();
      return;
    }
    this.closeDialog();
  }

  get isDialogOpen(): boolean {
    return !this.dialog.hidden;
  }

  closeDialog(): void {
    this.dialog.hidden = true;
    document.body.classList.remove('is-dialog');
    this.callbacks.onDialogClosed();
  }

  clearDialogAccent(): void {
    this.dialogAccent = '#31453b';
  }

  setDialogAccent(accent: string): void {
    this.dialogAccent = accent;
  }

  get dialogColor(): string {
    return this.dialogAccent;
  }

  toast(message: string, duration = 2800): void {
    window.clearTimeout(this.toastTimer);
    this.toastElement.textContent = message;
    this.toastElement.hidden = false;
    this.toastTimer = window.setTimeout(() => {
      this.toastElement.hidden = true;
    }, duration);
  }

  fadeToBlack(done: () => void): void {
    this.fade.classList.add('is-visible');
    window.setTimeout(done, 520);
  }

  fadeFromBlack(): void {
    window.setTimeout(() => this.fade.classList.remove('is-visible'), 60);
  }

  get isJournalOpen(): boolean {
    return !this.journal.hidden;
  }

  get isPauseOpen(): boolean {
    return !this.pause.hidden;
  }

  get isCreditsOpen(): boolean {
    return !this.credits.hidden;
  }
}
