import * as THREE from 'three';
import { damp, dampAngle } from '../core/math';
import { Character } from '../characters/character';
import type { CollisionWorld, LayoutSeat } from '../world/collision';

const WALK_SPEED = 2.7;
const RUN_SPEED = 5.2;
const RADIUS = 0.34;
const GRAVITY = 17;
const JUMP_SPEED = 5.1;

export interface PlayerStep {
  onFootstep?: (running: boolean) => void;
}

export class Player {
  readonly character: Character;
  readonly position = new THREE.Vector3();
  readonly velocity = new THREE.Vector3();
  yaw = 0;
  grounded = true;
  blocked = false;
  seatId: string | null = null;

  private verticalVelocity = 0;
  private stepAccumulator = 0;

  constructor(
    character: Character,
    private readonly collision: CollisionWorld,
    spawn: { x: number; z: number },
  ) {
    this.character = character;
    this.position.set(spawn.x, collision.groundAt(spawn.x, spawn.z), spawn.z);
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
  }

  get seated(): boolean {
    return this.seatId !== null;
  }

  teleport(x: number, z: number, yaw = this.yaw): void {
    this.seatId = null;
    this.character.setSeated(false);
    this.position.set(x, this.collision.groundAt(x, z), z);
    this.velocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
    this.yaw = yaw;
    this.character.setPosition(x, this.position.y, z);
    this.character.setYaw(yaw);
  }

  /** Settle into a chair or bench without walking there. */
  sit(seat: LayoutSeat): void {
    this.seatId = seat.id;
    this.position.set(seat.x, this.collision.groundAt(seat.x, seat.z), seat.z);
    this.velocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
    this.yaw = seat.yaw;
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
    this.character.setYaw(seat.yaw);
    this.character.setSeated(true);
  }

  /** Stand up just behind the seat and resolve any overlap with the furniture. */
  stand(): void {
    if (!this.seatId) return;
    const backX = Math.sin(this.yaw);
    const backZ = Math.cos(this.yaw);
    const targetX = this.position.x + backX * 0.95;
    const targetZ = this.position.z + backZ * 0.95;
    const resolved = this.collision.resolve(targetX, targetZ, RADIUS, this.position.y);
    this.seatId = null;
    this.character.setSeated(false);
    this.position.set(resolved.x, this.collision.groundAt(resolved.x, resolved.z), resolved.z);
    this.velocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
    this.character.setYaw(this.yaw);
  }

  update(dt: number, moveX: number, moveZ: number, running: boolean, jump: boolean, step: PlayerStep = {}): void {
    if (this.seated) {
      this.velocity.set(0, 0, 0);
      this.character.update(dt, { speed: 0, airborne: false });
      return;
    }

    const length = Math.hypot(moveX, moveZ);
    const targetX = length > 0.001 ? (moveX / length) * (running ? RUN_SPEED : WALK_SPEED) : 0;
    const targetZ = length > 0.001 ? (moveZ / length) * (running ? RUN_SPEED : WALK_SPEED) : 0;

    this.velocity.x = damp(this.velocity.x, targetX, this.grounded ? 14 : 4, dt);
    this.velocity.z = damp(this.velocity.z, targetZ, this.grounded ? 14 : 4, dt);

    if (length > 0.08) {
      const desiredYaw = Math.atan2(-moveX, -moveZ);
      this.yaw = dampAngle(this.yaw, desiredYaw, 11, dt);
    }

    if (jump && this.grounded) {
      this.verticalVelocity = JUMP_SPEED;
      this.grounded = false;
    }

    this.verticalVelocity -= GRAVITY * dt;
    let nextY = this.position.y + this.verticalVelocity * dt;

    const resolved = this.collision.resolve(
      this.position.x + this.velocity.x * dt,
      this.position.z + this.velocity.z * dt,
      RADIUS,
      this.position.y,
    );
    this.blocked = resolved.blocked;
    this.position.x = resolved.x;
    this.position.z = resolved.z;

    const ground = this.collision.groundAt(this.position.x, this.position.z);
    if (nextY <= ground + 0.001 && this.verticalVelocity <= 0) {
      // Walking up the castle stair produces a smooth ramp, so snapping is
      // safe here; the small threshold avoids stepping through the platform.
      if (ground - nextY < 0.65 || this.position.y < ground) {
        nextY = ground;
      }
      this.verticalVelocity = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }

    if (nextY < ground) nextY = ground;
    this.position.y = nextY;

    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
    this.character.setYaw(this.yaw);
    this.character.update(dt, { speed, airborne: !this.grounded });

    this.stepAccumulator += speed * dt;
    if (this.stepAccumulator > 1.95) {
      this.stepAccumulator = 0;
      step.onFootstep?.(speed > WALK_SPEED + 0.4);
    }
  }

  get speed(): number {
    return Math.hypot(this.velocity.x, this.velocity.z);
  }
}
