import * as THREE from 'three';
import { clamp, damp } from '../core/math';

export class CameraRig {
  yaw = 0;
  pitch = 0.22;
  distance = 4.6;
  sensitivity = 1;

  private readonly target = new THREE.Vector3();
  private readonly desired = new THREE.Vector3();
  private readonly lookAt = new THREE.Vector3();
  private cinematicAngle = 0.6;

  constructor(readonly camera: THREE.PerspectiveCamera) {}

  reset(yaw = 0): void {
    this.yaw = yaw;
    this.pitch = 0.22;
  }

  update(dt: number, focus: THREE.Vector3, look: { x: number; y: number }, snap = false): void {
    this.yaw -= look.x * 0.0026 * this.sensitivity;
    this.pitch = clamp(this.pitch + look.y * 0.0018 * this.sensitivity, -0.22, 0.92);

    this.target.set(focus.x, focus.y + 1.42, focus.z);

    const horizontal = Math.cos(this.pitch) * this.distance;
    this.desired.set(
      this.target.x + Math.sin(this.yaw) * horizontal,
      this.target.y + Math.sin(this.pitch) * this.distance,
      this.target.z + Math.cos(this.yaw) * horizontal,
    );

    if (snap) {
      this.camera.position.copy(this.desired);
    } else {
      this.camera.position.x = damp(this.camera.position.x, this.desired.x, 12, dt);
      this.camera.position.y = damp(this.camera.position.y, this.desired.y, 10, dt);
      this.camera.position.z = damp(this.camera.position.z, this.desired.z, 12, dt);
    }

    this.lookAt.set(this.target.x, this.target.y + 0.06, this.target.z);
    this.camera.lookAt(this.lookAt);
  }

  /** Slow drift over the town, used behind the title and character screens. */
  updateCinematic(dt: number, focus = new THREE.Vector3(-4.5, 7.8, 0)): void {
    this.cinematicAngle += dt * 0.022;
    const radius = 37;
    const height = 16.5 + Math.sin(this.cinematicAngle * 0.6) * 1.4;
    this.camera.position.set(
      focus.x + Math.sin(this.cinematicAngle) * radius,
      height,
      focus.z + Math.cos(this.cinematicAngle) * radius,
    );
    this.camera.lookAt(focus);
  }

  /** Horizontal forward direction of the view, flattened to the ground plane. */
  forward(target = new THREE.Vector3()): THREE.Vector3 {
    return target.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
  }

  right(target = new THREE.Vector3()): THREE.Vector3 {
    return target.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
  }
}
