export type Locale = 'id' | 'en';
export type Quality = 'low' | 'high';

export interface Settings {
  language: Locale;
  quality: Quality;
  curve: number;
  sensitivity: number;
  volume: number;
}

const STORAGE_KEY = 'dailylife.settings.v1';

export const DEFAULT_SETTINGS: Settings = {
  language: 'id',
  quality: 'high',
  curve: 1,
  sensitivity: 1,
  volume: 0.7,
};

export function loadSettings(): Settings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS };
    const parsed = JSON.parse(raw) as Partial<Settings>;
    return {
      language: parsed.language === 'en' ? 'en' : parsed.language === 'id' ? 'id' : DEFAULT_SETTINGS.language,
      quality: parsed.quality === 'low' ? 'low' : 'high',
      curve: clampNumber(parsed.curve, 0, 1.5, DEFAULT_SETTINGS.curve),
      sensitivity: clampNumber(parsed.sensitivity, 0.4, 2, DEFAULT_SETTINGS.sensitivity),
      volume: clampNumber(parsed.volume, 0, 1, DEFAULT_SETTINGS.volume),
    };
  } catch {
    return { ...DEFAULT_SETTINGS };
  }
}

export function hasStoredSettings(): boolean {
  try {
    return localStorage.getItem(STORAGE_KEY) !== null;
  } catch {
    return false;
  }
}

export function saveSettings(settings: Settings): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    // Private browsing can reject writes; the game still works for this session.
  }
}

function clampNumber(value: unknown, min: number, max: number, fallback: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, value));
}
