import i18next from 'i18next';
import type { Locale } from '../core/settings';
import en from './locales/en';
import id from './locales/id';

export const SUPPORTED_LOCALES: readonly Locale[] = ['id', 'en'] as const;

const resources = {
  id: { translation: id },
  en: { translation: en },
} as const;

let currentLocale: Locale = 'id';

export async function initI18n(locale: Locale): Promise<void> {
  currentLocale = locale;
  await i18next.init({
    lng: locale,
    fallbackLng: 'en',
    supportedLngs: [...SUPPORTED_LOCALES],
    resources,
    interpolation: { escapeValue: false },
    returnNull: false,
  });
  applyTranslations();
}

export function getLocale(): Locale {
  return currentLocale;
}

export async function setLocale(locale: Locale): Promise<void> {
  if (!SUPPORTED_LOCALES.includes(locale)) return;
  currentLocale = locale;
  await i18next.changeLanguage(locale);
  applyTranslations();
}

/** Translate a key. Missing keys return the key itself so layout problems are visible. */
export function t(key: string, options?: Record<string, unknown>): string {
  return String(options ? i18next.t(key, options as never) : i18next.t(key));
}

export function tList(key: string): string[] {
  const value = i18next.t(key, { returnObjects: true });
  return Array.isArray(value) ? value.map(String) : [];
}

/**
 * Update every element that carries a translation key. Called on boot and on
 * every language change; keeping this in one place prevents half-translated UI.
 */
export function applyTranslations(root?: ParentNode): void {
  if (typeof document === 'undefined') return;
  const scope = root ?? document;
  document.documentElement.lang = currentLocale;

  for (const element of scope.querySelectorAll<HTMLElement>('[data-i18n]')) {
    const key = element.dataset.i18n;
    if (key) element.textContent = t(key);
  }

  for (const element of scope.querySelectorAll<HTMLElement>('[data-i18n-aria-label]')) {
    const key = element.dataset.i18nAriaLabel;
    if (key) element.setAttribute('aria-label', t(key));
  }

  for (const element of scope.querySelectorAll<HTMLElement>('[data-i18n-placeholder]')) {
    const key = element.dataset.i18nPlaceholder;
    if (key) element.setAttribute('placeholder', t(key));
  }

  for (const element of scope.querySelectorAll<HTMLElement>('[data-i18n-title]')) {
    const key = element.dataset.i18nTitle;
    if (key) element.setAttribute('title', t(key));
  }

  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('dailylife:locale', { detail: { locale: currentLocale } }));
  }
}

/** Collect dotted key paths, used by tests to enforce parity between locales. */
export function flattenKeys(value: unknown, prefix = ''): string[] {
  if (value === null || typeof value !== 'object') return [prefix];
  const entries = Object.entries(value as Record<string, unknown>);
  if (entries.length === 0) return [prefix];
  return entries.flatMap(([key, child]) => flattenKeys(child, prefix ? `${prefix}.${key}` : key));
}
